1	// DevMemory dashboard — dependency-free SPA, hash-routed.
2	
3	const API = "/api";
4	const $ = (sel, root = document) => root.querySelector(sel);
5	const view = $("#view");
6	
7	// --- helpers ---------------------------------------------------------------
8	
9	const esc = (s) =>
10	  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
11	
12	const short = (sha) => (sha ? String(sha).slice(0, 12) : "—");
13	
14	async function api(path) {
15	  const r = await fetch(API + path);
16	  if (!r.ok) throw new Error((await r.text()) || r.statusText);
17	  const ct = r.headers.get("content-type") || "";
18	  return ct.includes("application/json") ? r.json() : r.text();
19	}
20	
21	function toast(msg) {
22	  const t = document.createElement("div");
23	  t.className = "toast";
24	  t.textContent = msg;
25	  document.body.appendChild(t);
26	  setTimeout(() => t.remove(), 4000);
27	}
28	
29	const badge = (label, cls) => `<span class="badge ${esc(cls ?? label)}"><span class="dot"></span>${esc(label)}</span>`;
30	
31	const loading = () => `<div class="empty"><span class="spin"></span></div>`;
32	const empty = (big, sub) => `<div class="empty"><div class="big">${esc(big)}</div>${sub ? esc(sub) : ""}</div>`;
33	
34	function metricChip(name, value) {
35	  return `<span class="pill">${esc(name)} <b>${esc(value)}</b></span>`;
36	}
37	
38	function pageHead(title, sub) {
39	  return `<div class="page-head"><h1>${esc(title)}</h1>${sub ? `<p>${esc(sub)}</p>` : ""}</div>`;
40	}
41	
42	// --- theme ---------------------------------------------------------------
43	
44	function initTheme() {
45	  const saved = (() => {
46	    try { return localStorage.getItem("devmemory-theme"); } catch { return null; }
47	  })();
48	  if (saved) document.documentElement.setAttribute("data-theme", saved);
49	  updateThemeLabel();
50	  $("#themeToggle").addEventListener("click", () => {
51	    const cur = document.documentElement.getAttribute("data-theme");
52	    const next = cur === "dark" ? "light" : "dark";
53	    document.documentElement.setAttribute("data-theme", next);
54	    try { localStorage.setItem("devmemory-theme", next); } catch {}
55	    updateThemeLabel();
56	  });
57	}
58	function updateThemeLabel() {
59	  const t = document.documentElement.getAttribute("data-theme");
60	  $("#themeLabel").textContent = t === "dark" ? "Dark" : t === "light" ? "Light" : "Theme";
61	}
62	
63	// --- router ------------------------------------------------------------
64	
65	const routes = {
66	  overview: renderOverview,
67	  timeline: renderTimeline,
68	  features: renderFeatures,
69	  feature: renderFeature,
70	  compare: renderCompare,
71	  memory: renderMemory,
72	  intelligence: renderIntelligence,
73	  search: renderSearch,
74	  version: renderVersion,
75	};
76	
77	async function router() {
78	  const hash = location.hash.slice(2) || "overview";
79	  const [name, ...rest] = hash.split("/");
80	  const fn = routes[name] || renderOverview;
81	  document.querySelectorAll(".nav-link").forEach((a) => a.classList.toggle("active", a.dataset.route === name));
82	  view.innerHTML = loading();
83	  try {
84	    await fn(rest.join("/"));
85	  } catch (e) {
86	    view.innerHTML = pageHead("Something went wrong") + empty(String(e.message || e));
87	    toast(String(e.message || e));
88	  }
89	  view.scrollTo?.(0, 0);
90	}
91	
92	// --- views -----------------------------------------------------------
93	
94	async function renderOverview() {
95	  const [p, versions, features] = await Promise.all([
96	    api("/project"),
97	    api("/versions?limit=8"),
98	    api("/features"),
99	  ]);
100	  $("#brandRepo").textContent = p.name;
101	  $("#foot").innerHTML = `${esc(p.repo_path)}`;
102	
103	  const recent = versions.slice().reverse();
104	  const done = features.filter((f) => f.status === "COMPLETE").length;
105	
106	  view.innerHTML =
107	    pageHead(p.name, `${p.branch ? "on " + p.branch + " · " : ""}${short(p.head_sha)}${p.head_subject ? " · " + p.head_subject : ""}`) +
108	    `<div class="grid cols-4" style="margin-bottom:16px">
109	      ${stat("Versions", p.version_count, p.latest_version_id ? "latest " + p.latest_version_id.toUpperCase() : "none yet")}
110	      ${stat("Latest result", p.latest_status ? "" : "—", "", p.latest_status ? badge(p.latest_status) : "")}
111	      ${stat("Features", `${done}/${features.length}`, "complete")}
112	      ${stat("Entire", p.entire_enabled ? "enabled" : p.entire_installed ? "off" : "absent", p.entire_version || "", "", p.entire_enabled ? "SUCCESS" : "NEEDS_REVIEW")}
113	    </div>` +
114	    (Object.keys(p.latest_metrics || {}).length
115	      ? `<div class="card card-pad" style="margin-bottom:16px"><div style="display:flex;gap:8px;flex-wrap:wrap">${Object.entries(p.latest_metrics).map(([k, v]) => metricChip(k, v)).join("")}</div></div>`
116	      : "") +
117	    (p.head_sha && !p.head_has_version
118	      ? `<div class="card card-pad" style="margin-bottom:16px;border-color:var(--warn)">HEAD (${short(p.head_sha)}) is not recorded yet — run <code>devmemory checkpoint</code>.</div>`
119	      : "") +
120	    `<div class="grid cols-2">
121	      <div class="card">
122	        <div class="card-head">Recent versions</div>
123	        ${recent.length ? recent.map(vrow).join("") : `<div class="card-pad muted">No versions yet.</div>`}
124	      </div>
125	      <div class="card">
126	        <div class="card-head">Feature health</div>
127	        ${features.length ? features.map(featRow).join("") : `<div class="card-pad muted">No features tracked.</div>`}
128	      </div>
129	    </div>`;
130	}
131	
132	function stat(label, value, foot, extra, valueClass) {
133	  return `<div class="card stat">
134	    <div class="label">${esc(label)}</div>
135	    <div class="value ${valueClass ? "" : ""}">${extra || esc(value)}</div>
136	    ${foot ? `<div class="foot">${esc(foot)}</div>` : ""}
137	  </div>`;
138	}
139	
140	function vrow(v) {
141	  const metrics = Object.entries(v.metrics || {}).slice(0, 2).map(([k, x]) => `${k} ${x}`).join(" · ");
142	  return `<a class="vrow" href="#/version/${esc(v.version_id)}">
143	    <div class="vid">${esc(v.version_id.toUpperCase())}</div>
144	    <div>${badge(v.status)}</div>
145	    <div>
146	      <div class="vintent">${esc(v.intent || "—")}</div>
147	      <div class="vmeta">
148	        <span>${esc(v.agent || "—")}</span>
149	        ${v.feature ? `<span>${esc(v.feature)}</span>` : ""}
150	        <span class="plus">+${v.lines_added}</span><span class="minus">-${v.lines_removed}</span>
151	        ${metrics ? `<span>${esc(metrics)}</span>` : ""}
152	      </div>
153	    </div>
154	    <div class="pill">${esc(short(v.git_commit))}</div>
155	  </a>`;
156	}
157	
158	function featRow(f) {
159	  const last = f.history[f.history.length - 1];
160	  return `<a class="vrow" style="grid-template-columns:1fr auto auto" href="#/feature/${encodeURIComponent(f.name)}">
161	    <div><div class="vintent">${esc(f.name)}</div><div class="vmeta"><span>${f.version_count} version${f.version_count === 1 ? "" : "s"}</span>${last ? `<span>${esc(last.version_id.toUpperCase())}</span>` : ""}</div></div>
162	    <div>${badge(f.status)}</div>
163	  </a>`;
164	}
165	
166	async function renderTimeline() {
167	  const versions = await api("/versions?limit=500");
168	  const ordered = versions.slice().reverse();
169	  view.innerHTML =
170	    pageHead("Version timeline", `${versions.length} development version${versions.length === 1 ? "" : "s"}`) +
171	    (ordered.length
172	      ? `<div class="card card-pad"><div class="timeline">${ordered.map(tlItem).join("")}</div></div>`
173	      : empty("No versions yet", "Make a commit, then run devmemory checkpoint."));
174	}
175	
176	function tlItem(v) {
177	  const metrics = Object.entries(v.metrics || {}).map(([k, x]) => metricChip(k, x)).join("");
178	  const conf = v.association_method === "trailer" || v.association_method === "none" ? "" :
179	    `<span class="badge uncertain"><span class="dot"></span>${esc(v.association_method)} ${v.association_confidence.toFixed(2)}</span>`;
180	  return `<div class="tl-item ${esc(v.status)}">
181	    <div class="tl-head">
182	      <a class="vid link" href="#/version/${esc(v.version_id)}">${esc(v.version_id.toUpperCase())}</a>
183	      ${badge(v.status)}
184	      ${v.checkpoint_id ? `<span class="pill">◈ ${esc(v.checkpoint_id.slice(0, 12))}</span>` : `<span class="badge missing"><span class="dot"></span>no checkpoint</span>`}
185	      ${conf}
186	      <span class="pill">${esc(short(v.git_commit))}</span>
187	    </div>
188	    <div class="tl-body">${esc(v.intent || "—")}</div>
189	    <div class="vmeta secondary" style="font-size:12.5px;margin-top:3px">
190	      ${esc(v.agent || "—")}${v.model ? " · " + esc(v.model) : ""}
191	      ${v.feature ? " · " + esc(v.feature) : ""}
192	      · <span class="plus">+${v.lines_added}</span> <span class="minus">-${v.lines_removed}</span> in ${v.files_changed} file${v.files_changed === 1 ? "" : "s"}
193	      ${v.tests_passed != null ? ` · ${v.tests_passed} passed / ${v.tests_failed} failed` : ""}
194	    </div>
195	    ${metrics ? `<div class="tl-metrics">${metrics}</div>` : ""}
196	  </div>`;
197	}
198	
199	async function renderVersion(id) {
200	  const [v, trace, attempts, impact] = await Promise.all([
201	    api("/versions/" + id),
202	    api(`/versions/${id}/trace`),
203	    api(`/versions/${id}/attempts`).catch(() => []),
204	    api(`/versions/${id}/impact`).catch(() => null),
205	  ]);
206	  let diff = "";
207	  try { diff = await api(`/versions/${id}/diff`); } catch {}
208	
209	  const cp = v.primary_checkpoint;
210	  view.innerHTML =
211	    pageHead(v.version_id.toUpperCase() + "  ·  " + v.status, v.intent || "") +
212	    `<div class="grid cols-2">
213	      <div class="card">
214	        <div class="card-head">Development trace</div>
215	        <div class="card-pad"><div class="trace">${trace.nodes.map(traceNode).join("")}</div></div>
216	      </div>
217	      <div>
218	        <div class="card" style="margin-bottom:16px">
219	          <div class="card-head">Record</div>
220	          <div class="card-pad">
221	            <dl class="kv">
222	              <dt>status</dt><dd>${badge(v.status)}</dd>
223	              <dt>agent</dt><dd>${esc(v.agent || "—")}${v.model ? ` <span class="muted">(${esc(v.model)})</span>` : ""}</dd>
224	              <dt>commit</dt><dd><span class="pill">${esc(short(v.git_commit))}</span> <span class="muted">parent ${esc(short(v.parent_commit))}</span></dd>
225	              <dt>branch</dt><dd>${esc(v.branch || "—")}</dd>
226	              <dt>feature</dt><dd>${v.feature_id ? esc(v.feature_id.split(":").pop()) : "—"}</dd>
227	              <dt>changes</dt><dd>${v.files_changed} files · <span class="plus">+${v.lines_added}</span> <span class="minus">-${v.lines_removed}</span></dd>
228	              ${v.tests && v.tests.command ? `<dt>tests</dt><dd>${v.tests.passed} passed / ${v.tests.failed} failed / ${v.tests.skipped} skipped</dd>` : ""}
229	              ${v.committed_at ? `<dt>committed</dt><dd class="muted">${esc(v.committed_at.slice(0, 16).replace("T", " "))}</dd>` : ""}
230	            </dl>
231	          </div>
232	        </div>
233	        ${cp ? `<div class="card" style="margin-bottom:16px">
234	          <div class="card-head">Entire checkpoint</div>
235	          <div class="card-pad">
236	            <dl class="kv">
237	              <dt>checkpoint</dt><dd><span class="pill">${esc(cp.checkpoint_id)}</span></dd>
238	              <dt>association</dt><dd>${badge(cp.association_method, cp.is_uncertain ? "uncertain" : "linked")} ${cp.association_confidence != null ? `<span class="muted">${cp.association_confidence.toFixed(2)}</span>` : ""}</dd>
239	              ${cp.agent ? `<dt>agent</dt><dd>${esc(cp.agent)}${cp.model ? " · " + esc(cp.model) : ""}</dd>` : ""}
240	              ${cp.tokens && cp.tokens.total ? `<dt>tokens</dt><dd>${(cp.tokens.total / 1000).toFixed(1)}k</dd>` : ""}
241	              ${cp.ref ? `<dt>ref</dt><dd class="muted mono" style="font-size:11px">${esc(cp.ref)}</dd>` : ""}
242	            </dl>
243	          </div>
244	        </div>` : ""}
245	        ${v.metrics && v.metrics.length ? `<div class="card">
246	          <div class="card-head">Metrics</div>
247	          <div class="card-pad">${v.metrics.map(metricRow).join("")}</div>
248	        </div>` : ""}
249	      </div>
250	    </div>` +
251	    (v.changed_files && v.changed_files.length ? `<div class="card" style="margin-top:16px">
252	      <div class="card-head">Files changed</div>
253	      <div class="card-pad files-list">${v.changed_files.map(fileRow).join("")}</div>
254	    </div>` : "") +
255	    (attempts.length ? `<div class="card" style="margin-top:16px;border-color:var(--warn)">
256	      <div class="card-head">⚠ Previous attempts touching this area</div>
257	      <div class="card-pad grid" style="gap:10px">${attempts.map(attemptCard).join("")}</div>
258	    </div>` : "") +
259	    (impact && impact.entities && impact.entities.length ? `<div class="card" style="margin-top:16px">
260	      <div class="card-head">Change impact <span class="muted" style="text-transform:none">· entire graph · ${impact.entities.length} entities</span></div>
261	      <div class="card-pad">${impactTable(impact)}</div>
262	    </div>` : "") +
263	    (v.analysis && v.analysis.summary ? `<div class="card" style="margin-top:16px">
264	      <div class="card-head">Analysis <span class="muted" style="text-transform:none">· ${esc(v.analysis.provider)}</span></div>
265	      <div class="card-pad"><p>${esc(v.analysis.summary)}</p>${v.analysis.recommendation ? `<p style="margin-top:8px"><b>Recommendation:</b> ${esc(v.analysis.recommendation)}</p>` : ""}</div>
266	    </div>` : "") +
267	    (diff ? `<div class="card" style="margin-top:16px">
268	      <div class="card-head">Diff · ${esc(short(v.parent_commit))} → ${esc(short(v.git_commit))}</div>
269	      ${renderDiff(diff)}
270	    </div>` : "");
271	}
272	
273	function impactTable(impact) {
274	  const rows = impact.entities.slice().sort((a, b) => (b.dependents_count - a.dependents_count));
275	  const cls = { removed: "down", signature_changed: "down", renamed: "", added: "up", body_changed: "" };
276	  return `<table class="mini"><thead><tr><th>change</th><th>entity</th><th>file</th><th style="text-align:right">deps</th></tr></thead><tbody>${
277	    rows.slice(0, 40).map((e) => `<tr>
278	      <td>${badge(e.change_type, cls[e.change_type] || "")}</td>
279	      <td>${esc(e.kind)} <b>${esc(e.name)}</b></td>
280	      <td class="muted mono" style="font-size:11px">${esc(e.path)}</td>
281	      <td style="text-align:right">${e.dependents_count || ""}</td>
282	    </tr>`).join("")
283	  }</tbody></table>${rows.length > 40 ? `<div class="muted" style="margin-top:6px">+${rows.length - 40} more</div>` : ""}`;
284	}
285	
286	function traceNode(n) {
287	  return `<div class="trace-node" data-source="${esc(n.source)}">
288	    <div class="t-label">${esc(n.label)}</div>
289	    <div>
290	      <div class="t-value">${esc(n.value)}${n.status ? " " + badge(n.status, n.status) : ""}</div>
291	      ${n.detail ? `<div class="t-detail">${esc(n.detail)}</div>` : ""}
292	    </div>
293	  </div>`;
294	}
295	
296	function metricRow(m) {
297	  const cls = m.is_improvement ? "up" : m.is_worse ? "down" : "";
298	  const arrow = m.before != null ? `${m.before} <span class="arrow">→</span> ${m.after}` : `${m.after}`;
299	  return `<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--border)">
300	    <span>${esc(m.name)}</span>
301	    <span class="metric-delta">${arrow}${m.unit ? " " + esc(m.unit) : ""} ${cls ? badge(cls, cls) : ""}</span>
302	  </div>`;
303	}
304	
305	function fileRow(f) {
306	  const mk = { added: "A", modified: "M", deleted: "D", renamed: "R", copied: "C", type_changed: "T" }[f.change_type] || "?";
307	  return `<div class="f"><span class="mark ${mk}">${mk}</span><span>${esc(f.path)}</span>${
308	    f.binary ? `<span class="muted">binary</span>` : `<span><span class="plus">+${f.additions}</span> <span class="minus">-${f.deletions}</span></span>`
309	  }</div>`;
310	}
311	
312	function renderDiff(text) {
313	  const lines = text.split("\n").slice(0, 4000).map((l) => {
314	    let cls = "";
315	    if (l.startsWith("+++") || l.startsWith("---") || l.startsWith("diff ") || l.startsWith("index ")) cls = "meta";
316	    else if (l.startsWith("@@")) cls = "hunk";
317	    else if (l.startsWith("+")) cls = "add";
318	    else if (l.startsWith("-")) cls = "del";
319	    return `<span class="l ${cls}">${esc(l) || " "}</span>`;
320	  });
321	  return `<div class="diff">${lines.join("")}</div>`;
322	}
323	
324	async function renderFeatures() {
325	  const features = await api("/features");
326	  view.innerHTML =
327	    pageHead("Features", "How each feature area evolved across versions") +
328	    (features.length
329	      ? `<div class="grid cols-2">${features.map(featCard).join("")}</div>`
330	      : empty("No features tracked yet", "Run devmemory checkpoint --feature <name>."));
331	}
332	
333	function featCard(f) {
334	  const spark = f.history.map((h) => `<a href="#/version/${esc(h.version_id)}" title="${esc(h.version_id.toUpperCase())} · ${esc(h.status)}">${badge(h.version_id.toUpperCase(), h.status)}</a>`).join(" ");
335	  return `<a class="card card-pad" href="#/feature/${encodeURIComponent(f.name)}" style="display:block">
336	    <div style="display:flex;justify-content:space-between;align-items:center">
337	      <b>${esc(f.name)}</b>${badge(f.status)}
338	    </div>
339	    <div class="muted" style="font-size:13px;margin:6px 0">${f.version_count} version${f.version_count === 1 ? "" : "s"}${
340	      Object.keys(f.latest_metrics).length ? " · " + Object.entries(f.latest_metrics).map(([k, v]) => `${k} ${v}`).join(", ") : ""
341	    }</div>
342	    <div style="display:flex;gap:5px;flex-wrap:wrap">${spark}</div>
343	  </a>`;
344	}
345	
346	async function renderFeature(name) {
347	  const f = await api("/features/" + encodeURIComponent(name));
348	  view.innerHTML =
349	    pageHead(f.name, `${badge(f.status)}`.replace(/<[^>]+>/g, "") + ` · ${f.version_count} versions`) +
350	    `<div class="card card-pad"><div class="timeline">${f.history
351	      .slice()
352	      .reverse()
353	      .map(
354	        (h) => `<div class="tl-item ${esc(h.status)}">
355	          <div class="tl-head"><a class="vid link" href="#/version/${esc(h.version_id)}">${esc(h.version_id.toUpperCase())}</a> ${badge(h.status)}</div>
356	          ${Object.keys(h.metrics).length ? `<div class="tl-metrics">${Object.entries(h.metrics).map(([k, v]) => metricChip(k, v)).join("")}</div>` : ""}
357	        </div>`
358	      )
359	      .join("")}</div></div>`;
360	}
361	
362	async function renderCompare(arg) {
363	  const versions = await api("/versions?limit=500");
364	  const [a, b] = (arg || "").split("...");
365	  const opts = (sel) => versions.map((v) => `<option value="${esc(v.version_id)}" ${v.version_id === sel ? "selected" : ""}>${esc(v.version_id.toUpperCase())} — ${esc((v.intent || "").slice(0, 50))}</option>`).join("");
366	
367	  view.innerHTML =
368	    pageHead("Compare versions", "What actually changed between two development states") +
369	    `<div class="card card-pad" style="margin-bottom:16px;display:flex;gap:12px;align-items:center">
370	      <select class="search-box" id="cmpA" style="flex:1">${opts(a)}</select>
371	      <span class="muted">→</span>
372	      <select class="search-box" id="cmpB" style="flex:1">${opts(b || (versions[versions.length - 1] || {}).version_id)}</select>
373	    </div>
374	    <div id="cmpResult">${empty("Pick two versions")}</div>`;
375	
376	  const run = async () => {
377	    const av = $("#cmpA").value, bv = $("#cmpB").value;
378	    location.hash = `#/compare/${av}...${bv}`;
379	    if (!av || !bv || av === bv) { $("#cmpResult").innerHTML = empty("Pick two different versions"); return; }
380	    $("#cmpResult").innerHTML = loading();
381	    try {
382	      const c = await api(`/compare?from=${encodeURIComponent(av)}&to=${encodeURIComponent(bv)}`);
383	      $("#cmpResult").innerHTML = compareResult(c);
384	    } catch (e) {
385	      $("#cmpResult").innerHTML = empty(String(e.message || e));
386	    }
387	  };
388	  $("#cmpA").addEventListener("change", run);
389	  $("#cmpB").addEventListener("change", run);
390	  if (a && b) run();
391	}
392	
393	function compareResult(c) {
394	  const mrows = c.metric_changes.map((m) => `<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--border)">
395	    <span>${esc(m.name)}</span>
396	    <span class="metric-delta">${m.before ?? "—"} <span class="arrow">→</span> ${m.after ?? "—"} ${m.delta != null ? `<span class="${m.delta >= 0 ? "plus" : "minus"}">(${m.delta >= 0 ? "+" : ""}${m.delta})</span>` : ""}</span>
397	  </div>`).join("");
398	  return `<div class="grid cols-2" style="margin-bottom:16px">
399	      <div class="card stat"><div class="label">Lines</div><div class="value"><span class="plus">+${c.stat.additions}</span> <span class="minus">-${c.stat.deletions}</span></div><div class="foot">${c.stat.files_changed} files</div></div>
400	      <div class="card stat"><div class="label">Status</div><div class="value">${badge(c.status_from)} → ${badge(c.status_to)}</div></div>
401	    </div>
402	    ${mrows ? `<div class="card" style="margin-bottom:16px"><div class="card-head">Metric changes</div><div class="card-pad">${mrows}</div></div>` : ""}
403	    ${c.test_changes && (c.test_changes.passed != null) ? `<div class="card card-pad" style="margin-bottom:16px">Tests: passed ${c.test_changes.passed >= 0 ? "+" : ""}${c.test_changes.passed}, failed ${c.test_changes.failed >= 0 ? "+" : ""}${c.test_changes.failed}</div>` : ""}
404	    <div class="card" style="margin-bottom:16px"><div class="card-head">Files</div><div class="card-pad files-list">${c.files.map(fileRow).join("") || `<span class="muted">no file changes</span>`}</div></div>
405	    ${c.diff_text ? `<div class="card"><div class="card-head">Diff</div>${renderDiff(c.diff_text)}</div>` : ""}`;
406	}
407	
408	async function renderMemory(arg) {
409	  const q = decodeURIComponent(arg || "");
410	  const attempts = await api("/attempts?limit=50" + (q ? "&q=" + encodeURIComponent(q) : ""));
411	  view.innerHTML =
412	    pageHead("Development memory", "Approaches that failed or regressed — so the next agent doesn't repeat them") +
413	    `<input class="search-box" id="mq" placeholder="scope by intent: token expiry, learning rate, auth …" value="${esc(q)}" style="margin-bottom:16px" />
414	     <div id="mres">${attemptList(attempts)}</div>`;
415	  const input = $("#mq");
416	  let t;
417	  input.addEventListener("input", () => {
418	    clearTimeout(t);
419	    t = setTimeout(async () => {
420	      const v = input.value.trim();
421	      location.hash = "#/memory/" + encodeURIComponent(v);
422	      $("#mres").innerHTML = loading();
423	      $("#mres").innerHTML = attemptList(await api("/attempts?limit=50" + (v ? "&q=" + encodeURIComponent(v) : "")));
424	    }, 250);
425	  });
426	}
427	
428	function attemptList(attempts) {
429	  if (!attempts.length) return empty("No relevant previous attempts", "Nothing to avoid — yet.");
430	  return `<div class="grid" style="gap:12px">${attempts.map(attemptCard).join("")}</div>`;
431	}
432	
433	function attemptCard(a) {
434	  return `<div class="card card-pad" style="border-left:3px solid ${a.is_adverse ? "var(--bad)" : "var(--border-strong)"}">
435	    <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
436	      <a class="vid link" href="#/version/${esc(a.version_id)}">${esc(a.version_id.toUpperCase())}</a>
437	      ${badge(a.status)}
438	      ${a.feature ? `<span class="pill">${esc(a.feature)}</span>` : ""}
439	      <span class="muted" style="margin-left:auto;font-size:12px">${esc(a.matched_on.join(" · "))}</span>
440	    </div>
441	    <div style="font-size:14px">${esc(a.intent || a.change_summary)}</div>
442	    <div class="secondary" style="font-size:13px;margin-top:4px">result: ${esc(a.result)}</div>
443	    ${a.recommendation ? `<div style="font-size:13px;margin-top:6px;color:var(--accent)">→ ${esc(a.recommendation)}</div>` : ""}
444	  </div>`;
445	}
446	
447	async function renderIntelligence() {
448	  const a = await api("/analytics");
449	  const t = (rows, cols) => `<table style="width:100%;border-collapse:collapse;font-size:13px">
450	    <thead><tr>${cols.map((c) => `<th style="text-align:${c.r ? "right" : "left"};padding:6px 8px;color:var(--text-muted);font-weight:500;border-bottom:1px solid var(--border)">${esc(c.h)}</th>`).join("")}</tr></thead>
451	    <tbody>${rows.map((row) => `<tr>${cols.map((c) => `<td style="text-align:${c.r ? "right" : "left"};padding:6px 8px;border-bottom:1px solid var(--border)">${row[c.k]}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
452	
453	  view.innerHTML =
454	    pageHead("Development intelligence", `source: ${a.source} · ${a.version_count} versions · ${a.regression_count} regressions · ${a.success_rate}% success`) +
455	    `<div class="grid cols-3" style="margin-bottom:16px">
456	      ${stat("Success rate", a.success_rate + "%", `${a.version_count} versions`)}
457	      ${stat("Regressions", a.regression_count, "flagged")}
458	      ${stat("Features", a.features.length, "tracked")}
459	    </div>
460	    <div class="grid cols-2">
461	      <div class="card"><div class="card-head">Regression leaderboard</div><div class="card-pad">${
462	        a.regressions.length ? t(a.regressions.map((r) => ({ v: `<a class="link" href="#/version/${r.version_id}">${r.version_id.toUpperCase()}</a>`, s: badge(r.severity, r.severity === "HIGH" ? "REGRESSION" : "PARTIAL_SUCCESS"), f: esc(r.feature || "-"), d: esc(r.detail) })), [{ h: "", k: "v" }, { h: "sev", k: "s" }, { h: "feature", k: "f" }, { h: "detail", k: "d" }]) : `<span class="muted">none</span>`
463	      }</div></div>
464	      <div class="card"><div class="card-head">Feature attempts</div><div class="card-pad">${
465	        t(a.features.map((f) => ({ n: esc(f.feature), a: f.attempts, s: f.success_rate + "%", r: f.regressions })), [{ h: "feature", k: "n" }, { h: "attempts", k: "a", r: 1 }, { h: "success", k: "s", r: 1 }, { h: "regr", k: "r", r: 1 }])
466	      }</div></div>
467	      <div class="card"><div class="card-head">File churn</div><div class="card-pad">${
468	        t(a.file_churn.map((f) => ({ p: `<span class="mono">${esc(f.path)}</span>`, c: f.changes, x: f.adverse_changes })), [{ h: "file", k: "p" }, { h: "changes", k: "c", r: 1 }, { h: "adverse", k: "x", r: 1 }])
469	      }</div></div>
470	      <div class="card"><div class="card-head">Agent effectiveness</div><div class="card-pad">${
471	        t(a.agents.map((g) => ({ a: esc(g.agent), v: g.versions, s: g.success_rate + "%", tk: g.tokens_per_success ? (g.tokens_per_success / 1000).toFixed(0) + "k" : "-" })), [{ h: "agent", k: "a" }, { h: "versions", k: "v", r: 1 }, { h: "success", k: "s", r: 1 }, { h: "tok/success", k: "tk", r: 1 }])
472	      }</div></div>
473	    </div>` +
474	    (a.trend.length > 1 ? `<div class="card" style="margin-top:16px"><div class="card-head">Trend</div><div class="card-pad">${sparkRow(a.trend)}</div></div>` : "") +
475	    (a.failed_approaches.length ? `<div class="card" style="margin-top:16px;border-color:var(--bad)">
476	      <div class="card-head">Repeatedly-failed approaches</div>
477	      <div class="card-pad">${a.failed_approaches.map((f) => `<div style="padding:6px 0;border-bottom:1px solid var(--border)"><b>${f.occurrences}×</b> <span class="mono">${esc(f.signature.join(", "))}</span> <span class="muted">${esc(f.example_intent || "")}</span> — ${f.version_ids.map((v) => `<a class="link" href="#/version/${v}">${v.toUpperCase()}</a>`).join(" ")}</div>`).join("")}</div>
478	    </div>` : "") +
479	    `<p class="muted" style="margin-top:16px;font-size:12px">${a.source === "databricks" ? "Live from Databricks Delta tables." : "Computed locally. Configure DATABRICKS_* to publish and query in Databricks."}</p>`;
480	}
481	
482	function sparkRow(trend) {
483	  const w = 620, h = 60, n = trend.length;
484	  const vals = trend.map((p) => (p.key_metric != null ? p.key_metric : p.test_pass_rate)).filter((x) => x != null);
485	  if (!vals.length) return `<span class="muted">no metric to trend</span>`;
486	  const mn = Math.min(...vals), mx = Math.max(...vals), rng = mx - mn || 1;
487	  const pts = trend.map((p, i) => {
488	    const v = p.key_metric != null ? p.key_metric : p.test_pass_rate;
489	    const x = (i / Math.max(1, n - 1)) * w;
490	    const y = v == null ? null : h - ((v - mn) / rng) * (h - 8) - 4;
491	    return { x, y, p };
492	  });
493	  const path = pts.filter((q) => q.y != null).map((q, i) => `${i ? "L" : "M"}${q.x.toFixed(1)},${q.y.toFixed(1)}`).join(" ");
494	  return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:${h}px">
495	    <path d="${path}" fill="none" stroke="var(--accent)" stroke-width="2"/>
496	    ${pts.filter((q) => q.y != null).map((q) => `<circle cx="${q.x.toFixed(1)}" cy="${q.y.toFixed(1)}" r="3" fill="${q.p.status === "REGRESSION" || q.p.status === "ERROR" ? "var(--bad)" : "var(--accent)"}"><title>${esc(q.p.version_id.toUpperCase())}: ${q.p.key_metric ?? q.p.test_pass_rate}</title></circle>`).join("")}
497	  </svg>`;
498	}
499	
500	async function renderSearch(q) {
501	  q = decodeURIComponent(q || "");
502	  view.innerHTML =
503	    pageHead("Search", "Across intent, agent, feature, files, commits, checkpoints, analysis") +
504	    `<input class="search-box" id="q" placeholder="authentication · learning rate · model.py · Codex …" value="${esc(q)}" style="margin-bottom:16px" />
505	     <div id="results">${q ? loading() : empty("Type to search")}</div>`;
506	  const input = $("#q");
507	  input.focus();
508	  let timer;
509	  const run = async () => {
510	    const val = input.value.trim();
511	    location.hash = "#/search/" + encodeURIComponent(val);
512	    if (!val) { $("#results").innerHTML = empty("Type to search"); return; }
513	    $("#results").innerHTML = loading();
514	    try {
515	      const r = await api("/search?q=" + encodeURIComponent(val));
516	      $("#results").innerHTML = r.count
517	        ? `<div class="card">${r.results.map((h) => `<a class="vrow" href="#/version/${esc(h.version_id)}">
518	            <div class="vid">${esc(h.version_id.toUpperCase())}</div>
519	            <div>${badge(h.status)}</div>
520	            <div><div class="vintent">${esc(h.snippet || h.intent || "—")}</div><div class="vmeta">${esc(h.agent || "—")}${h.feature ? " · " + esc(h.feature) : ""}</div></div>
521	            <div class="pill">${esc(short(h.git_commit))}</div>
522	          </a>`).join("")}</div>`
523	        : empty(`No matches for “${val}”`);
524	    } catch (e) {
525	      $("#results").innerHTML = empty(String(e.message || e));
526	    }
527	  };
528	  input.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(run, 250); });
529	  if (q) run();
530	}
531	
532	// --- boot ------------------------------------------------------------
533	
534	initTheme();
535	window.addEventListener("hashchange", router);
536	api("/project")
537	  .then((p) => { $("#brandRepo").textContent = p.name; })
538	  .catch(() => {});
539	router();
540

