import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useAttempts } from "@/api/client";
import { Async } from "@/components/Async";
import { PageHead, EmptyState } from "@/components/primitives";
import { AttemptCard } from "@/components/AttemptCard";
import { Icon } from "@/components/Icon";
import { useDebounced } from "@/lib/useDebounced";

export function Memory() {
  const { q: urlQ } = useParams<{ q: string }>();
  const navigate = useNavigate();
  const [q, setQ] = useState(urlQ ? decodeURIComponent(urlQ) : "");
  const debounced = useDebounced(q, 250);

  useEffect(() => {
    setQ(urlQ ? decodeURIComponent(urlQ) : "");
  }, [urlQ]);

  useEffect(() => {
    const path = debounced.trim() ? `/memory/${encodeURIComponent(debounced.trim())}` : "/memory";
    navigate(path, { replace: true });
  }, [debounced, navigate]);

  const query = useAttempts(debounced.trim());

  return (
    <>
      <PageHead
        title="Development memory"
        subtitle="Approaches that failed or regressed — so the next change (or agent) doesn't repeat them."
      />

      <div className="input-icon" style={{ marginBottom: 16 }}>
        <Icon name="search" size={15} />
        <input
          className="input"
          placeholder="Scope by intent — token expiry, discount logic, learning rate…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          autoFocus
        />
      </div>

      <Async
        query={query}
        isEmpty={(d) => d.length === 0}
        empty={
          <EmptyState
            icon="memory"
            title="No relevant previous attempts"
            sub="Nothing to avoid — yet."
          />
        }
      >
        {(attempts) => (
          <div className="stack" style={{ gap: 12 }}>
            {attempts.map((a) => (
              <AttemptCard key={a.version_id} a={a} />
            ))}
          </div>
        )}
      </Async>
    </>
  );
}

import { useEffect, useState } from "react";

export function useDebounced<T>(value: T, delay = 250): T {
  const [v, setV] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setV(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return v;
}

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useSearch } from "@/api/client";
import { Async } from "@/components/Async";
import { PageHead, EmptyState, StatusBadge } from "@/components/primitives";
import { Icon } from "@/components/Icon";
import { Link } from "react-router-dom";
import { shortSha, vlabel } from "@/lib/format";
import { useDebounced } from "@/lib/useDebounced";

export function Search() {
  const { q: urlQ } = useParams<{ q: string }>();
  const navigate = useNavigate();
  const [q, setQ] = useState(urlQ ? decodeURIComponent(urlQ) : "");
  const debounced = useDebounced(q, 250);

  useEffect(() => setQ(urlQ ? decodeURIComponent(urlQ) : ""), [urlQ]);
  useEffect(() => {
    navigate(debounced.trim() ? `/search/${encodeURIComponent(debounced.trim())}` : "/search", {
      replace: true,
    });
  }, [debounced, navigate]);

  const query = useSearch(debounced.trim());

  return (
    <>
      <PageHead
        title="Search"
        subtitle="Across intent, agent, feature, files, commits, checkpoints, and analysis."
      />
      <div className="input-icon" style={{ marginBottom: 16 }}>
        <Icon name="search" size={15} />
        <input
          className="input"
          placeholder="authentication · learning rate · core.py · Codex …"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          autoFocus
        />
      </div>

      {!debounced.trim() ? (
        <EmptyState icon="search" title="Type to search" />
      ) : (
        <Async
          query={query}
          isEmpty={(d) => d.count === 0}
          empty={<EmptyState icon="search" title={`No matches for “${debounced.trim()}”`} />}
        >
          {(res) => (
            <section className="card card--flush">
              {res.results.map((h) => (
                <Link key={h.version_id} className="vrow" to={`/version/${h.version_id}`}>
                  <span className="vrow__id">{vlabel(h.version_id)}</span>
                  <StatusBadge status={h.status} />
                  <span className="vrow__main">
                    <span className="vrow__intent truncate">
                      {h.snippet || h.intent || "—"}
                    </span>
                    <span className="vrow__meta">
                      {h.agent && <span>{h.agent}</span>}
                      {h.feature && <span>{h.feature}</span>}
                    </span>
                  </span>
                  <span className="pill vrow__sha">{shortSha(h.git_commit)}</span>
                </Link>
              ))}
            </section>
          )}
        </Async>
      )}
    </>
  );
}

import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { checkChange, useAnalytics } from "@/api/client";
import { Card, PageHead, Badge, EmptyState } from "@/components/primitives";
import { AttemptCard } from "@/components/AttemptCard";
import { Icon } from "@/components/Icon";
import { verdictTone } from "@/lib/status";
import type { ChangeGuidance } from "@/api/types";

export function SafeToChange() {
  const analytics = useAnalytics();
  const [files, setFiles] = useState("");
  const [intent, setIntent] = useState("");

  const mutation = useMutation<ChangeGuidance, Error, void>({
    mutationFn: () =>
      checkChange(
        files
          .split(/[\n,]+/)
          .map((s) => s.trim())
          .filter(Boolean),
        intent,
      ),
  });

  const churn = analytics.data?.file_churn ?? [];

  return (
    <>
      <PageHead
        title="Safe to change?"
        subtitle="A pre-flight risk read for the change you're about to make — the same check the MCP server gives an AI agent."
      />

      <div className="grid grid--2" style={{ alignItems: "start" }}>
        <Card title="What are you about to touch?" pad>
          <label className="field-label">Files</label>
          <textarea
            className="input"
            rows={4}
            placeholder={"pricing/core.py\nsrc/auth/tokens.py"}
            value={files}
            onChange={(e) => setFiles(e.target.value)}
            style={{ fontFamily: "var(--font-mono)", fontSize: "0.8125rem", resize: "vertical" }}
          />
          {churn.length > 0 && (
            <div className="row row--wrap" style={{ gap: 6, marginTop: 8 }}>
              <span className="muted text-xs">frequently changed:</span>
              {churn.slice(0, 6).map((c) => (
                <button
                  key={c.path}
                  className="pill"
                  onClick={() =>
                    setFiles((f) => (f.split(/[\n,]+/).map((s) => s.trim()).includes(c.path) ? f : (f ? f + "\n" : "") + c.path))
                  }
                >
                  {c.path}
                  {c.adverse_changes > 0 && <span className="minus"> ⚠{c.adverse_changes}</span>}
                </button>
              ))}
            </div>
          )}

          <label className="field-label" style={{ marginTop: 14 }}>
            Intent
          </label>
          <input
            className="input"
            placeholder="e.g. change the discount tier logic"
            value={intent}
            onChange={(e) => setIntent(e.target.value)}
          />

          <button
            className="btn btn--primary"
            style={{ marginTop: 14, width: "100%" }}
            disabled={!files.trim() || mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            {mutation.isPending ? <span className="spinner" /> : <Icon name="shield" size={15} />}
            Check
          </button>
        </Card>

        <div>
          {mutation.isIdle && (
            <EmptyState
              icon="shield"
              title="No check run yet"
              sub="Add the files you're about to edit and describe the change."
            />
          )}
          {mutation.isError && (
            <EmptyState icon="alert" title="Check failed" sub={mutation.error.message} />
          )}
          {mutation.data && <Guidance g={mutation.data} />}
        </div>
      </div>
    </>
  );
}

function Guidance({ g }: { g: ChangeGuidance }) {
  const tone = verdictTone(g.verdict);
  return (
    <div className="stack">
      <Card className={`callout callout--${tone === "ok" ? "ok" : tone === "bad" ? "bad" : "warn"}`} pad>
        <div className="row" style={{ gap: 10, alignItems: "flex-start" }}>
          <Icon name={tone === "ok" ? "check" : "alert"} size={20} />
          <div>
            <div className="row" style={{ gap: 8, marginBottom: 4 }}>
              <Badge tone={tone}>{g.verdict}</Badge>
            </div>
            <div style={{ fontSize: "0.9375rem", fontWeight: 550 }}>{g.headline}</div>
          </div>
        </div>
      </Card>

      {g.warnings.length > 0 && (
        <Card title="Warnings" pad>
          <ul className="warn-list">
            {g.warnings.map((w, i) => (
              <li key={i}>
                <Icon name="alert" size={13} /> {w}
              </li>
            ))}
          </ul>
        </Card>
      )}

      {g.recommendations.length > 0 && (
        <Card title="Recommendations" pad>
          <ul className="rec-list">
            {g.recommendations.map((r, i) => (
              <li key={i}>
                <Icon name="arrowRight" size={13} /> {r}
              </li>
            ))}
          </ul>
        </Card>
      )}

      {g.related_attempts.length > 0 && (
        <Card title={`Related previous attempts · ${g.related_attempts.length}`} pad>
          <div className="stack" style={{ gap: 10 }}>
            {g.related_attempts.map((a) => (
              <AttemptCard key={a.version_id} a={a} />
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

import type { ReactNode } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

const AXIS = { fontSize: 11, fill: "var(--text-muted)" };
const GRID = "var(--border)";

function TipBox({ children }: { children: ReactNode }) {
  return (
    <div
      style={{
        background: "var(--bg-elevated)",
        border: "1px solid var(--border-strong)",
        borderRadius: "var(--r-2)",
        padding: "8px 10px",
        boxShadow: "var(--shadow-md)",
        fontSize: "0.75rem",
        lineHeight: 1.5,
      }}
    >
      {children}
    </div>
  );
}

/* -- metric / rate trend over versions -------------------------------- */

export interface TrendDatum {
  label: string;
  value: number | null;
  adverse: boolean;
  sub?: string;
}

export function TrendChart({ data, unit }: { data: TrendDatum[]; unit?: string }) {
  return (
    <ResponsiveContainer width="100%" height={220}>
      <LineChart data={data} margin={{ top: 8, right: 16, bottom: 4, left: -8 }}>
        <CartesianGrid stroke={GRID} vertical={false} />
        <XAxis dataKey="label" tick={AXIS} tickLine={false} axisLine={{ stroke: GRID }} />
        <YAxis tick={AXIS} tickLine={false} axisLine={false} width={44} />
        <Tooltip
          cursor={{ stroke: "var(--border-strong)" }}
          content={({ active, payload }) =>
            active && payload?.length ? (
              <TipBox>
                <b>{payload[0].payload.label}</b>
                {payload[0].payload.sub && <div className="muted">{payload[0].payload.sub}</div>}
                <div>
                  {payload[0].value}
                  {unit ? ` ${unit}` : ""}
                </div>
              </TipBox>
            ) : null
          }
        />
        <Line
          type="monotone"
          dataKey="value"
          stroke="var(--series-1)"
          strokeWidth={2}
          connectNulls
          dot={(props: { cx?: number; cy?: number; payload?: TrendDatum; index?: number }) => {
            const { cx, cy, payload } = props;
            if (cx == null || cy == null) return <g key={props.index} />;
            return (
              <circle
                key={props.index}
                cx={cx}
                cy={cy}
                r={payload?.adverse ? 4.5 : 3}
                fill={payload?.adverse ? "var(--bad)" : "var(--series-1)"}
                stroke="var(--bg-elevated)"
                strokeWidth={2}
              />
            );
          }}
          activeDot={{ r: 5 }}
        />
      </LineChart>
    </ResponsiveContainer>
  );
}

/* -- horizontal magnitude bars -------------------------------------- */

export interface BarDatum {
  label: string;
  value: number;
  sub?: string;
  tone?: string;
}

export function HBarChart({ data, unit }: { data: BarDatum[]; unit?: string }) {
  return (
    <ResponsiveContainer width="100%" height={Math.max(120, data.length * 40 + 24)}>
      <BarChart data={data} layout="vertical" margin={{ top: 4, right: 24, bottom: 4, left: 8 }}>
        <CartesianGrid stroke={GRID} horizontal={false} />
        <XAxis type="number" tick={AXIS} tickLine={false} axisLine={{ stroke: GRID }} domain={[0, unit === "%" ? 100 : "auto"]} />
        <YAxis
          type="category"
          dataKey="label"
          tick={AXIS}
          tickLine={false}
          axisLine={false}
          width={110}
        />
        <Tooltip
          cursor={{ fill: "var(--bg-sunken)" }}
          content={({ active, payload }) =>
            active && payload?.length ? (
              <TipBox>
                <b>{payload[0].payload.label}</b>
                <div>
                  {payload[0].value}
                  {unit ?? ""}
                </div>
                {payload[0].payload.sub && <div className="muted">{payload[0].payload.sub}</div>}
              </TipBox>
            ) : null
          }
        />
        <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={16}>
          {data.map((d, i) => (
            <Cell key={i} fill={d.tone ?? "var(--series-1)"} />
          ))}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  );
}

/* -- churn scatter ------------------------------------------------- */

export interface ScatterDatum {
  x: number;
  y: number;
  label: string;
}

export function ChurnScatter({ data }: { data: ScatterDatum[] }) {
  return (
    <ResponsiveContainer width="100%" height={240}>
      <ScatterChart margin={{ top: 12, right: 20, bottom: 20, left: -4 }}>
        <CartesianGrid stroke={GRID} />
        <XAxis
          type="number"
          dataKey="x"
          name="changes"
          tick={AXIS}
          tickLine={false}
          axisLine={{ stroke: GRID }}
          label={{ value: "total changes", position: "insideBottom", offset: -12, fontSize: 11, fill: "var(--text-muted)" }}
        />
        <YAxis
          type="number"
          dataKey="y"
          name="adverse"
          tick={AXIS}
          tickLine={false}
          axisLine={false}
          width={40}
          label={{ value: "adverse", angle: -90, position: "insideLeft", fontSize: 11, fill: "var(--text-muted)" }}
        />
        <Tooltip
          cursor={{ strokeDasharray: "3 3" }}
          content={({ active, payload }) =>
            active && payload?.length ? (
              <TipBox>
                <b className="mono">{payload[0].payload.label}</b>
                <div>
                  {payload[0].payload.x} changes · {payload[0].payload.y} adverse
                </div>
              </TipBox>
            ) : null
          }
        />
        <Scatter data={data} fill="var(--series-1)">
          {data.map((d, i) => (
            <Cell key={i} fill={d.y > 0 ? "var(--bad)" : "var(--series-1)"} />
          ))}
        </Scatter>
      </ScatterChart>
    </ResponsiveContainer>
  );
}

