import { Link } from "react-router-dom";
import { useAnalytics } from "@/api/client";
import { Async } from "@/components/Async";
import { Card, PageHead, StatTile, Badge, EmptyState } from "@/components/primitives";
import { ChurnScatter, HBarChart, TrendChart } from "@/components/charts";
import { Icon } from "@/components/Icon";
import { pct, vlabel } from "@/lib/format";
import { severityTone } from "@/lib/status";

export function Intelligence() {
  const query = useAnalytics();

  return (
    <>
      <Async query={query}>
        {(a) => {
          const usesMetric = a.trend.some((t) => t.key_metric != null);
          return (
            <>
              <PageHead
                title="Development intelligence"
                subtitle={
                  <>
                    {a.version_count} versions · {a.regression_count} regressions ·{" "}
                    {pct(a.success_rate)} success
                  </>
                }
                actions={
                  <Badge tone={a.source === "databricks" ? "info" : "neutral"}>
                    <Icon name={a.source === "databricks" ? "external" : "history"} size={12} />
                    {a.source === "databricks" ? "Databricks" : "local"}
                  </Badge>
                }
              />

              <div className="grid grid--3" style={{ marginBottom: 16 }}>
                <StatTile
                  label="Success rate"
                  value={pct(a.success_rate)}
                  sub={`${a.version_count} versions`}
                  tone={a.success_rate >= 80 ? "ok" : a.success_rate >= 50 ? "warn" : "bad"}
                />
                <StatTile label="Regressions" value={a.regression_count} sub="flagged" tone={a.regression_count ? "warn" : "ok"} />
                <StatTile label="Features" value={a.features.length} sub="tracked" />
              </div>

              {a.failed_approaches.length > 0 && (
                <Card className="callout callout--bad" title="Repeatedly-failed approaches" pad>
                  <div className="stack" style={{ gap: 8 }}>
                    {a.failed_approaches.map((f, i) => (
                      <div key={i} className="row row--wrap" style={{ gap: 10 }}>
                        <Badge tone="bad">{f.occurrences}×</Badge>
                        <span className="mono text-sm truncate">{f.signature.join(", ")}</span>
                        {f.example_intent && (
                          <span className="muted text-sm truncate">“{f.example_intent}”</span>
                        )}
                        <span className="spacer" />
                        {f.version_ids.map((v) => (
                          <Link key={v} className="link" to={`/version/${v}`}>
                            {vlabel(v)}
                          </Link>
                        ))}
                      </div>
                    ))}
                  </div>
                </Card>
              )}

              <div className="grid grid--2" style={{ alignItems: "start", marginTop: 16 }}>
                <Card title={usesMetric ? "Key metric over versions" : "Test pass rate over versions"} pad>
                  {a.trend.length > 1 ? (
                    <TrendChart
                      data={a.trend.map((t) => ({
                        label: vlabel(t.version_id),
                        value: usesMetric ? t.key_metric : t.test_pass_rate,
                        adverse: t.status === "REGRESSION" || t.status === "ERROR",
                        sub: t.status,
                      }))}
                    />
                  ) : (
                    <EmptyState title="Not enough versions to trend" />
                  )}
                </Card>

                <Card title="Feature success rate" pad>
                  {a.features.length ? (
                    <HBarChart
                      unit="%"
                      data={a.features.map((f) => ({
                        label: f.feature,
                        value: Math.round(f.success_rate),
                        sub: `${f.successes}/${f.attempts} attempts · ${f.regressions} regressions`,
                        tone:
                          f.success_rate >= 80
                            ? "var(--ok)"
                            : f.success_rate >= 50
                              ? "var(--warn)"
                              : "var(--bad)",
                      }))}
                    />
                  ) : (
                    <EmptyState title="No features" />
                  )}
                </Card>

                <Card title="File churn vs. adverse changes" pad>
                  {a.file_churn.length ? (
                    <ChurnScatter
                      data={a.file_churn.map((f) => ({
                        x: f.changes,
                        y: f.adverse_changes,
                        label: f.path,
                      }))}
                    />
                  ) : (
                    <EmptyState title="No churn data" />
                  )}
                </Card>

                <Card title="Agent effectiveness" flush>
                  <div className="dm-table__scroll">
                    <table className="dm-table">
                      <thead>
                        <tr>
                          <th>agent</th>
                          <th className="r">versions</th>
                          <th className="r">success</th>
                          <th className="r">tok/success</th>
                        </tr>
                      </thead>
                      <tbody>
                        {a.agents.map((g) => (
                          <tr key={g.agent}>
                            <td>{g.agent}</td>
                            <td className="r">{g.versions}</td>
                            <td className="r">{pct(g.success_rate)}</td>
                            <td className="r">
                              {g.tokens_per_success ? `${(g.tokens_per_success / 1000).toFixed(0)}k` : "—"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </Card>
              </div>

              <Card title="Regression leaderboard" flush style={{ marginTop: 16 }}>
                {a.regressions.length === 0 ? (
                  <div className="card--pad muted">No regressions recorded.</div>
                ) : (
                  <div className="dm-table__scroll">
                    <table className="dm-table">
                      <thead>
                        <tr>
                          <th>version</th>
                          <th>severity</th>
                          <th>feature</th>
                          <th>detail</th>
                        </tr>
                      </thead>
                      <tbody>
                        {a.regressions.map((r) => (
                          <tr key={r.version_id}>
                            <td>
                              <Link className="link" to={`/version/${r.version_id}`}>
                                {vlabel(r.version_id)}
                              </Link>
                            </td>
                            <td>
                              <Badge tone={severityTone(r.severity)}>{r.severity}</Badge>
                            </td>
                            <td className="muted">{r.feature ?? "—"}</td>
                            <td className="text-sm">{r.detail}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </Card>

              <p className="muted text-xs" style={{ marginTop: 16 }}>
                {a.source === "databricks"
                  ? "Live from Databricks Delta tables."
                  : "Computed locally from the SQLite store. Set DATABRICKS_* and databricks.enabled to publish and query these in Databricks."}
              </p>
            </>
          );
        }}
      </Async>
    </>
  );
}

/* ============================================================================
   Component styles. Tokens come from theme.css.
   ========================================================================= */

/* ---- sidebar --------------------------------------------------------- */

.sidebar-wrap {
  position: relative;
  z-index: 40;
}
.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 16px 12px;
  background: var(--bg-elevated);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.sidebar__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px 16px;
}
.sidebar__name {
  font-weight: 680;
  letter-spacing: -0.02em;
  font-size: 0.95rem;
}
.sidebar__repo {
  font-size: 0.6875rem;
  color: var(--text-muted);
}
.sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.nav-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 10px;
  border-radius: var(--r-2);
  font-size: 0.8438rem;
  font-weight: 520;
  color: var(--text-secondary);
  transition: background var(--dur-1) var(--ease), color var(--dur-1) var(--ease);
}
.nav-link:hover {
  background: var(--bg-hover);
  color: var(--text);
}
.nav-link--active {
  background: var(--accent-soft);
  color: var(--accent-text);
  font-weight: 580;
}
.nav-link--active svg {
  color: var(--accent);
}
.sidebar__foot {
  font-size: 0.6875rem;
  color: var(--text-muted);
  padding: 10px 8px 4px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-top: 1px solid var(--border);
}

.sidebar-scrim {
  display: none;
}

@media (max-width: 960px) {
  .sidebar-wrap {
    position: fixed;
    inset: 0;
    pointer-events: none;
  }
  .sidebar {
    position: fixed;
    left: 0;
    top: 0;
    width: var(--sidebar-w);
    transform: translateX(-100%);
    transition: transform var(--dur-2) var(--ease);
    box-shadow: var(--shadow-lg);
  }
  .sidebar-wrap--open {
    pointer-events: auto;
  }
  .sidebar-wrap--open .sidebar {
    transform: translateX(0);
  }
  .sidebar-wrap--open .sidebar-scrim {
    display: block;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.35);
    animation: routeFade var(--dur-2) var(--ease);
  }
}

/* ---- topbar --------------------------------------------------------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 10px;
  height: var(--topbar-h);
  padding: 0 16px;
  background: color-mix(in srgb, var(--bg) 82%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.topbar__menu {
  display: none;
}
.topbar__context {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 0.8125rem;
}
.topbar__search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  min-width: 200px;
  border-radius: var(--r-2);
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  color: var(--text-muted);
  font-size: 0.8125rem;
  transition: border-color var(--dur-1) var(--ease);
}
.topbar__search:hover {
  border-color: var(--border-strong);
}
.topbar__search kbd {
  margin-left: auto;
}
@media (max-width: 960px) {
  .topbar__menu {
    display: inline-flex;
  }
  .topbar__search span:not(kbd) {
    display: none;
  }
  .topbar__search {
    min-width: 0;
  }
}

/* ---- command palette ---------------------------------------------- */

.palette-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(10, 11, 16, 0.4);
  backdrop-filter: blur(2px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  animation: routeFade var(--dur-1) var(--ease);
}
.palette {
  width: min(600px, 92vw);
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: var(--r-3);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  animation: paletteIn var(--dur-2) var(--ease);
}
@keyframes paletteIn {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.98);
  }
}
.palette__input {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-muted);
}
.palette__field {
  flex: 1;
  border: none;
  background: none;
  outline: none;
  font-size: 0.9375rem;
  color: var(--text);
}
.palette__list {
  max-height: 52vh;
  overflow-y: auto;
  padding: 6px;
}
.palette__group {
  font-size: 0.6875rem;
  font-weight: 620;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 10px 10px 4px;
}
.palette__item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--r-2);
  font-size: 0.8438rem;
  color: var(--text-secondary);
  text-align: left;
}
.palette__item--active {
  background: var(--accent-soft);
  color: var(--accent-text);
}
.palette__title {
  flex: 1;
  min-width: 0;
}
.palette__hint {
  font-size: 0.75rem;
  color: var(--text-muted);
  max-width: 40%;
}
.palette__empty {
  padding: 28px;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ---- stat tile -------------------------------------------------- */

.stat-tile {
  padding: 15px 17px;
}
.stat-tile__label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.6875rem;
  font-weight: 560;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.stat-tile__value {
  font-size: 1.65rem;
  font-weight: 660;
  letter-spacing: -0.03em;
  margin-top: 5px;
  line-height: 1.1;
}
.stat-tile__value--ok {
  color: var(--ok);
}
.stat-tile__value--bad {
  color: var(--bad);
}
.stat-tile__value--warn {
  color: var(--warn);
}
.stat-tile__sub {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 3px;
}

/* ---- callout --------------------------------------------------- */

.callout {
  border-width: 1px;
  border-style: solid;
}
.callout--warn {
  border-color: var(--warn-border);
  background: color-mix(in srgb, var(--warn-soft) 55%, var(--bg-elevated));
}
.callout--bad {
  border-color: var(--bad-border);
  background: color-mix(in srgb, var(--bad-soft) 45%, var(--bg-elevated));
}
.callout--ok {
  border-color: var(--ok-border);
  background: color-mix(in srgb, var(--ok-soft) 45%, var(--bg-elevated));
}
.callout .card__head {
  border-color: inherit;
}

/* ---- version row (lists) ------------------------------------- */

.vrow {
  display: grid;
  grid-template-columns: 46px auto 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 11px 18px;
  border-bottom: 1px solid var(--border);
  transition: background var(--dur-1) var(--ease);
}
.vrow:last-child {
  border-bottom: none;
}
.vrow:hover {
  background: var(--bg-sunken);
}
.vrow__id {
  font-weight: 660;
  font-size: 0.8125rem;
}
.vrow__main {
  min-width: 0;
}
.vrow__intent {
  font-size: 0.875rem;
}
.vrow__meta {
  display: flex;
  gap: 10px;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
  flex-wrap: wrap;
}
.vrow__sha {
  justify-self: end;
}
@media (max-width: 640px) {
  .vrow {
    grid-template-columns: 40px 1fr;
    row-gap: 6px;
  }
  .vrow__sha {
    display: none;
  }
}

/* ---- feature row (overview) --------------------------------- */

.frow {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 18px;
  border-bottom: 1px solid var(--border);
  transition: background var(--dur-1) var(--ease);
}
.frow:last-child {
  border-bottom: none;
}
.frow:hover {
  background: var(--bg-sunken);
}
.frow__name {
  flex: 1;
  min-width: 0;
  font-size: 0.875rem;
  font-weight: 520;
}
.frow__dots {
  display: flex;
  gap: 4px;
}

/* ---- health strip ----------------------------------------- */

.health-strip {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 24px;
  align-items: center;
}
.health-strip__dots {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.health-strip__dot {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: var(--r-2);
  font-size: 0.625rem;
  font-weight: 640;
  border: 1.5px solid var(--border-strong);
  color: var(--text-secondary);
  transition: transform var(--dur-1) var(--ease);
}
.health-strip__dot:hover {
  transform: translateY(-2px);
}
.health-strip__dot--ok {
  border-color: var(--ok);
  color: var(--ok-strong);
  background: var(--ok-soft);
}
.health-strip__dot--bad {
  border-color: var(--bad);
  color: var(--bad-strong);
  background: var(--bad-soft);
}
.health-strip__dot--warn {
  border-color: var(--warn);
  color: var(--warn-strong);
  background: var(--warn-soft);
}
.health-strip__spark {
  min-width: 0;
}
@media (max-width: 720px) {
  .health-strip {
    grid-template-columns: 1fr;
    gap: 14px;
  }
}

/* ---- timeline rail --------------------------------------- */

.tl {
  position: relative;
  padding: 6px 18px 6px 14px;
}
.tl__item {
  position: relative;
  display: grid;
  grid-template-columns: 22px 1fr;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.tl__item:last-child {
  border-bottom: none;
}
.tl__item::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 26px;
  bottom: -14px;
  width: 2px;
  background: var(--border);
}
.tl__item:last-child::before {
  display: none;
}
.tl__dot {
  width: 12px;
  height: 12px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 2.5px solid var(--border-strong);
  z-index: 1;
}
.tl__item--ok .tl__dot {
  border-color: var(--ok);
}
.tl__item--bad .tl__dot {
  border-color: var(--bad);
}
.tl__item--warn .tl__dot {
  border-color: var(--warn);
}
.tl__item--info .tl__dot {
  border-color: var(--info);
}
.tl__intent {
  font-size: 0.9375rem;
  margin-top: 6px;
}
.tl__sub {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* ---- segmented control --------------------------------- */

.segmented {
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  background: var(--bg-sunken);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
}
.segmented__btn {
  padding: 5px 11px;
  border-radius: var(--r-1);
  font-size: 0.75rem;
  font-weight: 540;
  color: var(--text-secondary);
}
.segmented__btn--active {
  background: var(--bg-elevated);
  color: var(--text);
  box-shadow: var(--shadow-xs);
}

/* ---- feature cards ------------------------------------ */

.feat-card {
  display: block;
  transition: border-color var(--dur-1) var(--ease), transform var(--dur-1) var(--ease);
}
.feat-card:hover {
  border-color: var(--border-accent);
  transform: translateY(-1px);
}
.feat-card__track {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.feat-card__node {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border-radius: var(--r-1);
  background: var(--bg-sunken);
  border: 1px solid var(--border);
  font-size: 0.6875rem;
}
.feat-card__vid {
  font-weight: 620;
}

/* ---- subnav (version detail) ------------------------- */

.subnav {
  position: sticky;
  top: var(--topbar-h);
  z-index: 20;
  display: flex;
  gap: 4px;
  padding: 8px 0;
  margin-bottom: 8px;
  background: color-mix(in srgb, var(--bg) 82%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.subnav__link {
  padding: 5px 11px;
  border-radius: var(--r-2);
  font-size: 0.8125rem;
  font-weight: 520;
  color: var(--text-secondary);
}
.subnav__link:hover {
  background: var(--bg-hover);
}
.subnav__link--active {
  background: var(--accent-soft);
  color: var(--accent-text);
}
.scroll-mt {
  scroll-margin-top: calc(var(--topbar-h) + 52px);
}

/* ---- trace ------------------------------------------ */

.trace {
  display: flex;
  flex-direction: column;
}
.trace__node {
  position: relative;
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 14px;
  padding: 10px 0 10px 20px;
}
.trace__node::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 15px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.trace__node--entire::before {
  background: var(--info);
  box-shadow: 0 0 0 3px var(--info-soft);
}
.trace__node--status::before,
.trace__node--analysis::before {
  background: var(--warn);
  box-shadow: 0 0 0 3px var(--warn-soft);
}
.trace__node:not(:last-child)::after {
  content: "";
  position: absolute;
  left: 8px;
  top: 24px;
  bottom: -10px;
  width: 2px;
  background: var(--border-strong);
}
.trace__label {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  padding-top: 2px;
}
.trace__value {
  font-size: 0.875rem;
  font-weight: 500;
  word-break: break-word;
}
.trace__detail {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 2px;
}

/* ---- metric rows ---------------------------------- */

.metric-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.875rem;
}
.metric-row:last-child {
  border-bottom: none;
}

/* ---- files list ---------------------------------- */

.files {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.files__row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 0;
  font-size: 0.8125rem;
}
.files__mark {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  display: grid;
  place-items: center;
  font-size: 0.625rem;
  font-weight: 700;
  flex: none;
  background: var(--bg-sunken);
  color: var(--text-muted);
}
.files__mark--added {
  background: var(--ok-soft);
  color: var(--ok-strong);
}
.files__mark--modified {
  background: var(--warn-soft);
  color: var(--warn-strong);
}
.files__mark--deleted {
  background: var(--bad-soft);
  color: var(--bad-strong);
}
.files__mark--renamed,
.files__mark--copied {
  background: var(--info-soft);
  color: var(--info-strong);
}

/* ---- kv list ------------------------------------ */

.kv {
  display: grid;
  grid-template-columns: 96px 1fr;
  gap: 7px 14px;
  font-size: 0.875rem;
}
.kv dt {
  color: var(--text-muted);
  font-size: 0.8125rem;
}
.kv dd {
  word-break: break-word;
}

/* ---- attempt card ------------------------------ */

.attempt {
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-2);
  padding: 12px 14px;
  background: var(--bg-elevated);
}
.attempt--adverse {
  border-left-color: var(--bad);
}
.attempt__rec {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  font-size: 0.8125rem;
  color: var(--accent-text);
}

/* ---- warn / rec lists ------------------------- */

.warn-list,
.rec-list {
  list-style: none;
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.warn-list li,
.rec-list li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.8438rem;
}
.warn-list li svg {
  color: var(--warn);
  margin-top: 2px;
  flex: none;
}
.rec-list li svg {
  color: var(--accent);
  margin-top: 2px;
  flex: none;
}

/* ---- diff viewer ------------------------------ */

.diff {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  max-height: 620px;
  overflow: auto;
}
.diff__file {
  border-bottom: 1px solid var(--border);
}
.diff__file:last-child {
  border-bottom: none;
}
.diff__file-head {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 14px;
  background: var(--bg-sunken);
  border-bottom: 1px solid var(--border);
  font-size: 0.75rem;
  text-align: left;
}
.diff__body {
  overflow-x: auto;
}
.diff__line {
  display: grid;
  grid-template-columns: 44px 44px 16px 1fr;
  align-items: baseline;
}
.diff__gutter {
  text-align: right;
  padding: 0 8px;
  color: var(--text-muted);
  opacity: 0.6;
  user-select: none;
  font-size: 0.6875rem;
}
.diff__mark {
  text-align: center;
  color: var(--text-muted);
}
.diff__text {
  white-space: pre;
  padding-right: 14px;
}
.diff__line--add {
  background: var(--ok-soft);
}
.diff__line--add .diff__text,
.diff__line--add .diff__mark {
  color: var(--ok-strong);
}
.diff__line--del {
  background: var(--bad-soft);
}
.diff__line--del .diff__text,
.diff__line--del .diff__mark {
  color: var(--bad-strong);
}
.diff__line--hunk {
  background: var(--info-soft);
}
.diff__line--hunk .diff__text {
  color: var(--info-strong);
  white-space: pre-wrap;
}

