// Minimal CDP driver: node cdp.mjs <url> <outPng> <width> <height> [evalJs]
// Requires a Chrome started with --remote-debugging-port=9222
const [, , url, out, wRaw, hRaw, evalJs] = process.argv;
const width = Number(wRaw || 1440);
const height = Number(hRaw || 900);

const targets = await (await fetch("http://127.0.0.1:9222/json/list")).json();
let page = targets.find((t) => t.type === "page");
if (!page) {
  page = await (await fetch("http://127.0.0.1:9222/json/new?about:blank")).json();
}

const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const send = (method, params = {}, sessionId) =>
  new Promise((res, rej) => {
    const msgId = ++id;
    pending.set(msgId, { res, rej });
    ws.send(JSON.stringify({ id: msgId, method, params, sessionId }));
  });

await new Promise((r) => (ws.onopen = r));
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) {
    const { res, rej } = pending.get(m.id);
    pending.delete(m.id);
    m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result);
  }
};

await send("Page.enable");
await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", {
  width,
  height,
  deviceScaleFactor: 2,
  mobile: width < 700,
});
await send("Page.navigate", { url });
await new Promise((r) => setTimeout(r, 2500));

if (evalJs) {
  const r = await send("Runtime.evaluate", { expression: evalJs, returnByValue: true, awaitPromise: true });
  console.log(JSON.stringify(r.result?.value ?? r.result, null, 2));
  await new Promise((r) => setTimeout(r, 600));
}

if (out && out !== "-") {
  const shot = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true });
  const { writeFileSync } = await import("node:fs");
  writeFileSync(out, Buffer.from(shot.data, "base64"));
  console.log("wrote " + out);
}
ws.close();
process.exit(0);

